import{_ as l,C as t,o as s,c as o,E as a,a2 as d}from"./chunks/framework.uPk2SrVb.js";const f=JSON.parse('{"title":"有用的科学回退，仍然改变了任务","description":"","frontmatter":{"title":"有用的科学回退，仍然改变了任务","date":"2026-10-31","column":"digital-employee","category":"daily","article_type":"case-study","edition":"research-center","research_question":"方法改变后的科学回退，能否算原任务完成？（When a scientific fallback changes the requested method, which executable-input evidence prevents relabeling it as completion of the original task?）","summary":"存档输入显示，两态等权请求被四态等权回退替代。输入一致性检查可以保留方法差异，却不能替代化学有效性或变更授权的证据。","sources":["https://arxiv.org/html/2610.38145v1","https://borealisdata.ca/api/access/datafile/1260621"],"pageClass":"runtime-v6-article","item_id":"SIG-20261031-005","lifecycle":"Published","cover":"/assets/covers/daily-2026-10-31-sig-20261031-005-final-cover.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"zh/digital-employee/2026-10-31-sig-20261031-005.md","filePath":"zh/digital-employee/2026-10-31-sig-20261031-005.md","lastUpdated":null}'),n={name:"zh/digital-employee/2026-10-31-sig-20261031-005.md"};function h(p,e,c,g,u,m){const r=t("ArticleCover"),i=t("ArticleTableScroll");return s(),o("div",null,[a(r,{image:"/assets/covers/daily-2026-10-31-sig-20261031-005-final-cover.png",kicker:"研究成果",title:"有用的科学回退，仍然改变了任务",summary:"存档输入显示，两态等权请求被四态等权回退替代。输入一致性检查可以保留方法差异，却不能替代化学有效性或变更授权的证据。",version:"2026-10-31",languageHref:"/en/digital-employee/2026-10-31-sig-20261031-005",languageLabel:"English"}),a(i,{language:"zh"}),e[0]||(e[0]=d('<h1 id="有用的科学回退-仍然改变了任务" tabindex="-1">有用的科学回退，仍然改变了任务 <a class="header-anchor" href="#有用的科学回退-仍然改变了任务" aria-label="Permalink to &quot;有用的科学回退，仍然改变了任务&quot;">​</a></h1><h2 id="一个有价值的结果-为什么还不能算原任务完成" tabindex="-1">一个有价值的结果，为什么还不能算原任务完成 <a class="header-anchor" href="#一个有价值的结果-为什么还不能算原任务完成" aria-label="Permalink to &quot;一个有价值的结果，为什么还不能算原任务完成&quot;">​</a></h2><p>Quntur（科学研究智能体系统）的案例 006 留下了一组值得并列阅读的材料：作者报告，回退计算得到了约 4.661449045 电子伏特的能隙；同一份存档摘要又明确记录，它不符合最初请求的两态平均协议。两句话可以同时成立。前者谈结果的用途，后者谈任务的方法身份。<a href="https://borealisdata.ca/api/access/datafile/1260621" target="_blank" rel="noreferrer">存档案例审计与输入</a></p><p>对于开发科学数字员工的工程师，问题在于验收记录能否保留这种差别。若只把能隙或进程结束作为“完成”的依据，系统就会失去解释“实际交付了什么”的能力。本案例支持一个有限判断：有用的科学回退仍需保留与原请求的协议差异。这里没有把输入核对当成化学复现，也没有据此断言历史操作未经批准。</p><h2 id="三个输入字段揭示的方法变化" tabindex="-1">三个输入字段揭示的方法变化 <a class="header-anchor" href="#三个输入字段揭示的方法变化" aria-label="Permalink to &quot;三个输入字段揭示的方法变化&quot;">​</a></h2><p>“根”在这组计算中对应纳入求解的电子态；两根等权表示两个态各占一半权重，四根等权则是四个态各占四分之一。参与平均的对象与权重发生变化，不能只因最终数值接近参考值就认定方法未变。</p><p>本次内部输入一致性实验解析了存档中三个具有成员级哈希的可执行输入，结果如下。表格反映输入设置，不是重新运行计算所得的收敛结论。</p><table tabindex="0"><thead><tr><th>存档输入</th><th style="text-align:right;">根数</th><th>权重</th><th style="text-align:right;">最大迭代设置</th></tr></thead><tbody><tr><td>案例 006 初始请求</td><td style="text-align:right;">2</td><td>0.5、0.5</td><td style="text-align:right;">200</td></tr><tr><td>案例 006 回退</td><td style="text-align:right;">4</td><td>四个 0.25</td><td style="text-align:right;">1</td></tr><tr><td>案例 018 严格最终输入</td><td style="text-align:right;">2</td><td>0.5、0.5</td><td style="text-align:right;">50</td></tr></tbody></table><p>来源：本次内部实验对<a href="https://borealisdata.ca/api/access/datafile/1260621" target="_blank" rel="noreferrer">存档可执行输入</a>的解析。内部实验不是独立第三方复现。原始摘要也直接将案例 006 的“两态协议匹配”字段记为假，因此方法替代既有输入差异，也有作者自己的限定说明。</p><p>案例 018 的两根等权输入提供了正对照：检查器能够识别符合狭义两态约束的输入，而非一概拒绝科学任务。空白和注释变化也没有改变解析结果。不过，最大迭代设置为 1 只说明回退输入的配置，不能从该字段单独推断是否收敛。</p><p>实验过程还有一次已修正的失败：最初的解析器按裸权重写法读取，而实际输入采用带索引的权重赋值，导致正对照断言失败。修正后才得到上述结果；这是本地检查工具的错误，不是上游计算程序的缺陷。该经历也说明，验收检查器自身必须有真实格式的正对照。</p><h2 id="把替代交付和原请求分别留下来" tabindex="-1">把替代交付和原请求分别留下来 <a class="header-anchor" href="#把替代交付和原请求分别留下来" aria-label="Permalink to &quot;把替代交付和原请求分别留下来&quot;">​</a></h2><p>作者的案例审计称，数值收敛之后仍出现活性空间逃逸，两态恢复没有得到所需的稳定结果，最终采用带限定的四态固定轨道回退。上述轨道解释和恢复过程属于作者报告；本次没有重算原始输出，也没有独立识别轨道图。<a href="https://borealisdata.ca/api/access/datafile/1260621" target="_blank" rel="noreferrer">案例 006 审计</a></p><p>这使验收责任更具体：记录请求协议与实际协议，保留数值停止状态，另外说明领域有效性和变更授权的依据。它们可以出现在同一份完成回执中，但不能相互替代。输入差异回答“执行了哪一种方法”；领域审查回答“该结果在什么范围内可信”；授权记录回答“谁同意了变化”。</p><p>这是一项基于案例的工程解释，并非已测量过的通用验收方案。实际系统若允许替代交付，可以将其标为带限定的结果，并把方法变化交还给有权决策的人。这样既保留回退的科学价值，也让使用者知道原请求尚缺哪一项验收证据。</p><p>反过来，不能把本案例写成作者隐瞒变化的故事：作者已经披露回退的限定。审计称指定运行缺少完整动作与审批轨迹，回顾性记忆也不足以建立批准事实；但缺少记录不等于历史上从未批准。现有证据支持保留未知，不能支持指控。</p><h2 id="证据与引用" tabindex="-1">证据与引用 <a class="header-anchor" href="#证据与引用" aria-label="Permalink to &quot;证据与引用&quot;">​</a></h2><p>公开一手材料直接支持输入字段与摘要标记的事实；作者陈述支持其能隙、轨道判断和恢复经过的报告。本次内部实验只核对输入设置，研究解释则把这些事实连接到验收记录设计。这里没有独立第三方检验相同化学结果的证据。</p><p>主要文献是作者的<a href="https://arxiv.org/html/2610.38145v1" target="_blank" rel="noreferrer">研究预印本，版本一</a>，材料是作者存放于学术数据平台的<a href="https://borealisdata.ca/api/access/datafile/1260621" target="_blank" rel="noreferrer">轨迹审计、输入与摘要</a>。本次研究日期为 2026-10-31；引用定位包括论文第 2.2 至 3.1 节、附录，以及案例 006 和 018 的审计目录。预印本版本和数据归档建立来源身份，不能自动建立结论正确性。引用也不代表认可全部作者判断。</p><p>论文报告了 32 个固定几何结构、六种自动活性空间选择协议的比较，最佳统一方案的平均绝对误差为 0.459 电子伏特，系统报告值为 0.239 电子伏特。这些是作者结果，本次没有复现。四个案例存在参考态不匹配，方法限定也没有被作为缺失能隙惩罚；因此该数字比较是数值接近程度，不能直接改写为普遍的目标态准确性优势。<a href="https://arxiv.org/html/2610.38145v1" target="_blank" rel="noreferrer">论文结果及附录</a></p><p>封面为依据所引输入差异创作的编辑性图像，用计算层数的差异表达方法身份；它不承担分子结构、轨道或数值机制解释。</p><h2 id="输入检查之后-仍有哪些问题" tabindex="-1">输入检查之后，仍有哪些问题 <a class="header-anchor" href="#输入检查之后-仍有哪些问题" aria-label="Permalink to &quot;输入检查之后，仍有哪些问题&quot;">​</a></h2><p>这个检查器只覆盖根数、权重和最大迭代设置，不是完整的计算输入解析器。案例 018 虽保留两态等权，其审计仍将全局最低单重态身份留为未知；案例 006 对原协议有效态的判断也仍然未知。两态匹配的正对照不能消除这些领域问题。</p><p>本次没有下载并重算全部原始计算输出或会话档案，没有完成 32 例复现，也没有完整归档校验和的验证；成员级哈希只能绑定已提取的成员字节。轨道图没有独立视觉分类，资源效率优势也缺少可比的逐例遥测。少数重复运行不能排除未来路径分歧。</p><p>下一步真正需要的证据，是预先承诺的态与梯度验收标准、可追溯到该标准的输出，以及可认证的方法变更授权。补齐它们之前，最可靠的交付方式是把已经得到的替代结果与尚未完成的原协议验收同时呈现。</p>',25))])}const b=l(n,[["render",h]]);export{f as __pageData,b as default};
